// Zirkuläre Abhängigkeiten vermeiden: nur Typ-Imports
type BurrowSystemType   = {
  isBurrowed(id: string): boolean;
  isStunned(id: string): boolean;
  isDashBlocked(id: string): boolean;
  getMovementSpeedFactor(id: string): number;
  getPhase?(id: string): BurrowPhase;
};
type LoadoutManagerType = {
  getSpeedMultiplier(id: string, now: number): number;
  getHeldSelfPushVelocity(id: string, now: number): { vx: number; vy: number } | null;
};

interface DashState {
  readonly id: number;
  phase:   1 | 2;
  startMs: number;   // Zeitstempel Phasenbeginn
  dirX:    number;   // normierter Startrichtungsvektor
  dirY:    number;
  vNorm:   number;   // v_norm zum Dash-Zeitpunkt (skaliert mit Buffs)
  impulseMultiplier: number;
  isBurrowDash: boolean;
  hitIds: Set<string>;
  lastGroundX: number;
  lastGroundY: number;
}

/**
 * Gegner behalten ihren quadratischen Burst mit anschließender Erholung, ohne
 * Spieler-Upgrades, Air-Control oder Burrow-Impuls.
 */
interface EnemyDashState {
  phase:   1 | 2;
  startMs: number;
  dirX:    number;
  dirY:    number;
  vNorm:   number;
}

type DashGroundFireHandler = (
  playerId: string,
  sourceKey: string,
  fromX: number,
  fromY: number,
  toX: number,
  toY: number,
  durationMs: number,
  now: number,
) => void;

interface ExternalImpulse {
  vx: number;
  vy: number;
  startMs: number;
  durationMs: number;
  sourcePlayerId?: string;
}

interface RecentImpulseSource {
  sourcePlayerId: string;
  expiresAt: number;
}

interface WalkingStep {
  dx: number;
  dy: number;
  /** Host-resolved walking speed including the frame's time-bubble factor. */
  speed: number;
  assisted: boolean;
  positionRevision: number;
}

interface ForcedMovement {
  vx: number;
  vy: number;
}

export class HostPhysicsSystem {
  private readonly movementStepObservers = new Set<(id: string, x: number, y: number, revision: number) => void>();

  observeMovementSteps(observer: (id: string, x: number, y: number, revision: number) => void): () => void {
    this.movementStepObservers.add(observer);
    return () => { this.movementStepObservers.delete(observer); };
  }
  private readonly movementAcknowledgements = new PlayerMovementAcknowledgements();
  private movementPhysicsWorld: Phaser.Physics.Arcade.World | null = null;
  /** Ordinary walking of this frame, re-resolved before every fixed step (see consumeMovementStep). */
  private readonly walkingSteps = new Map<string, WalkingStep>();
  private readonly consumeMovementStep = (deltaSeconds: number): void => {
    if (!this.bridge.isHost()) return;
    for (const player of this.playerManager.getAllPlayers()) {
      const body = player.physicsProxy.body as Phaser.Physics.Arcade.Body | null;
      if (!player.active || !body?.enable) continue;
      for (const observer of this.movementStepObservers) observer(player.id, body.center.x, body.center.y, player.positionRevision);
      this.movementAcknowledgements.consume(player.id, player.positionRevision, deltaSeconds * 1000);
      // Client prediction resolves the walking rule from the pose before each fixed step. The
      // host must do the same instead of letting a render frame's later steps reuse a velocity
      // chosen from an older pose and already clipped by Arcade's collision response.
      const walking = this.walkingSteps.get(player.id);
      if (!walking || walking.positionRevision !== player.positionRevision) continue;
      resolveWalkingVelocity(body.center.x, body.center.y, walking.dx, walking.dy, walking.speed,
        this.worldMetrics, walking.assisted ? this.assistedMovementBlocked : null, this.gridCornerAssistOutput);
      body.setVelocity(this.gridCornerAssistOutput.dx, this.gridCornerAssistOutput.dy);
    }
  };
  private readonly commitMovementStep = (): void => {
    if (!this.bridge.isHost()) return;
    for (const player of this.playerManager.getAllPlayers()) {
      if (player.active && player.physicsProxy.body) this.movementAcknowledgements.commit(player.id, player);
    }
  };

  private interruptMovement(id: string): void {
    this.movementAcknowledgements.interrupt(id);
    this.walkingSteps.delete(id);
  }

  getMovementPredictionState(id: string, now = Date.now()): PlayerMovementPredictionState | undefined {
    const player = this.playerManager.getPlayer(id);
    if (!player) return undefined;
    const state = this.movementAcknowledgements.snapshot(id, player);
    // Combat and held actions can interrupt after the velocity selection in this frame.
    if (state.canPredict && (!this.combatSystem?.isAlive(id) || this.stunChecker?.(id, now)
      || this.burrowSystem?.isStunned(id) || this.burrowSystem?.isBurrowed(id)
      || (this.burrowSystem?.getPhase?.(id) ?? 'idle') !== 'idle'
      || this.dashStates.has(id) || this.mountedPlayers.has(id) || this.forcedMovement.has(id)
      || this.pendingRecoils.has(id) || this.loadoutManager?.getHeldSelfPushVelocity(id, now))) {
      this.interruptMovement(id);
      return this.movementAcknowledgements.snapshot(id, player);
    }
    return state;
  }
  private dashSequence = 0;
  private dashObserver: {
    start(id: string, now: number): void;
    move(step: ZeusMovement & { readonly dashId: number }, now: number): void;
    end(id: string, dashId?: number): void;
    /** A body-contact attack may defer the wider impact until its own contact has resolved. */
    canApplyImpact?(id: string, targetId: string): boolean;
  } | null = null;
  private stunChecker: ((id: string, now: number) => boolean) | null = null;
  private zeusMoveBonus: ((id: string, now: number) => number) | null = null;
  setDashObserver(observer: HostPhysicsSystem['dashObserver']): void { this.dashObserver = observer; }
  setStunChecker(checker: HostPhysicsSystem['stunChecker']): void { this.stunChecker = checker; }
  setZeusMoveBonus(resolver: HostPhysicsSystem['zeusMoveBonus']): void { this.zeusMoveBonus = resolver; }
  getDashMovement(id: string): (ZeusMovement & { readonly dashId: number }) | null {
    const dash = this.dashStates.get(id), p = this.playerManager.getPlayer(id);
    return dash && p ? { playerId: id, dashId: dash.id, x: p.x, y: p.y,
      radius: p.getCollisionRadius(), positionRevision: p.positionRevision } : null;
  }
  private publishDashMovement(id: string, now: number): void {
    if (!this.dashObserver) return;
    const step = this.getDashMovement(id); if (step) this.dashObserver?.move(step, now);
  }

  private scene:         Phaser.Scene;
  private playerManager: PlayerManager;
  private bridge:        NetworkBridge;
  private combatSystem:  (CombatActorStatePort & CombatDamageEffectPort) | null;

  // Obstacle-Gruppen – werden nach Arena-Aufbau injiziert
  private rockGroup:   Phaser.Physics.Arcade.StaticGroup | null = null;
  private trunkGroup:  Phaser.Physics.Arcade.StaticGroup | null = null;
  private baseGroup:   Phaser.Physics.Arcade.StaticGroup | null = null;

  // Pro-Spieler Collider-Tracking
  private rockCollidersSetup  = new Set<string>();
  private trunkCollidersSetup = new Set<string>();
  private baseCollidersSetup  = new Set<string>();
  private playerColliders     = new Map<string, Phaser.Physics.Arcade.Collider[]>();
  private enemyRockCollidersSetup  = new Set<string>();
  private enemyTrunkCollidersSetup = new Set<string>();
  private enemyBaseCollidersSetup  = new Set<string>();
  private enemyColliders           = new Map<string, Phaser.Physics.Arcade.Collider[]>();
  private burrowedEnemies          = new Set<string>();

  // Optionale Referenzen
  private burrowSystem:   BurrowSystemType   | null = null;
  private burrowDashExitHandler: ((playerId: string) => boolean) | null = null;
  private loadoutManager: LoadoutManagerType | null = null;
  private timeBubbleSystem: TimeBubbleSystem | null = null;
  private enemyManager: EnemyManager | null = null;
  private walkingSpeedMultiplierResolver: ((playerId: string, now: number) => number) | null = null;
  private runSpeedResolver: ((playerId: string) => number) | null = null;
  private dashRangeMultiplierResolver: ((playerId: string) => number) | null = null;
  private dashRecoveryDurationResolver: ((playerId: string) => number) | null = null;
  private dashImpactDamageResolver: ((playerId: string) => number) | null = null;
  private dashImpactKnockbackResolver: ((playerId: string) => number) | null = null;
  private dashGroundFireDurationResolver: ((playerId: string) => number) | null = null;
  private dashGroundFireHandler: DashGroundFireHandler | null = null;
  private dashHoldEnabledResolver: ((playerId: string) => boolean) | null = null;
  private enemyMovementFactorResolver: ((enemyId: string, now: number) => number) | null = null;
  private enemyHitStaggerResolver: ((enemyId: string, now: number) => boolean) | null = null;
  private enemyRockContactCallback: ((enemyId: string, rock: RockPhysicsProxy, now: number) => void) | null = null;
  private canMoveResolver: ((playerId: string) => boolean) | null = null;
  private movementBlockedCellResolver: MovementBlockedCell | null = null;
  private worldMetrics: WorldMetrics | null = null;
  private readonly gridCornerAssistOutput: GridCornerAssistOutput = { dx: 0, dy: 0 };

  // Dash-Zustand pro Spieler (2-Phasen Speed-Debt-Modell)
  private dashStates       = new Map<string, DashState>();
  private dashBurstPlayers = new Set<string>(); // Phase 1 aktiv → Schießen blockiert
  private enemyDashStates  = new Map<string, EnemyDashState>();

  // Burrow-State (Collider-Enable-Tracking)
  private burrowedPlayers = new Set<string>();

  // Rückstoß-Impulse (Zeit-basiertes Quad-Ease-Out Decay über mehrere Frames)
  private pendingRecoils = new Map<string, ExternalImpulse[]>();
  private recentImpulseSources = new Map<string, RecentImpulseSource>();
  private forcedMovement = new Map<string, ForcedMovement>();
  private readonly mountedPlayers = new Map<string, { x: number; y: number }>();

  hasForcedMovement(id: string): boolean { return this.forcedMovement.has(id); }

  setPlayerMounted(id: string, position: { x: number; y: number } | null): void {
    const player = this.playerManager.getPlayer(id);
    if (position) {
      if (!this.mountedPlayers.has(id)) this.interruptMovement(id);
      this.mountedPlayers.set(id, { x: position.x, y: position.y });
      this.pendingRecoils.delete(id);
      this.recentImpulseSources.delete(id);
      this.forcedMovement.delete(id);
      if (player?.body) {
        player.body.reset(position.x, position.y);
        player.body.setVelocity(0, 0);
        player.body.enable = false;
      }
    } else {
      this.mountedPlayers.delete(id);
      if (player?.body) player.body.enable = this.combatSystem?.isAlive(id) ?? false;
    }
  }

  constructor(
    scene:         Phaser.Scene,
    playerManager: PlayerManager,
    bridge:        NetworkBridge,
    combatSystem:  (CombatActorStatePort & CombatDamageEffectPort) | null = null,
  ) {
    this.scene         = scene;
    this.playerManager = playerManager;
    this.bridge        = bridge;
    this.combatSystem  = combatSystem;
  }

  // ── Referenz-Injection ────────────────────────────────────────────────────

  setBurrowSystem(bs: BurrowSystemType | null): void       { this.burrowSystem   = bs; }
  setBurrowDashExitHandler(handler: ((playerId: string) => boolean) | null): void { this.burrowDashExitHandler = handler; }
  /** World binding; the returned lease cannot clear a later World's Combat port. */
  bindCombatCore(combatSystem: CombatActorStatePort & CombatDamageEffectPort): { destroy(): void } {
    this.combatSystem = combatSystem;
    return { destroy: () => {
      if (this.combatSystem === combatSystem) this.combatSystem = null;
    } };
  }
  setLoadoutManager(lm: LoadoutManagerType | null): void  { this.loadoutManager = lm; }
  setTimeBubbleSystem(system: TimeBubbleSystem | null): void { this.timeBubbleSystem = system; }

  getWorldMovementFactorAt(x: number, y: number, now = Date.now()): number {
    return this.timeBubbleSystem?.getPlayerMovementFactorAt(x, y, now) ?? 1;
  }
  setEnemyManager(manager: EnemyManager | null): void { this.enemyManager = manager; }
  setCanMoveResolver(resolver: ((playerId: string) => boolean) | null): void { this.canMoveResolver = resolver; }
  setWalkingSpeedMultiplierResolver(resolver: ((playerId: string, now: number) => number) | null): void { this.walkingSpeedMultiplierResolver = resolver; }
  setRunSpeedResolver(resolver: ((playerId: string) => number) | null): void { this.runSpeedResolver = resolver; }
  setDashRangeMultiplierResolver(resolver: ((playerId: string) => number) | null): void { this.dashRangeMultiplierResolver = resolver; }
  setDashRecoveryDurationResolver(resolver: ((playerId: string) => number) | null): void { this.dashRecoveryDurationResolver = resolver; }
  setDashImpactDamageResolver(resolver: ((playerId: string) => number) | null): void { this.dashImpactDamageResolver = resolver; }
  setDashImpactKnockbackResolver(resolver: ((playerId: string) => number) | null): void { this.dashImpactKnockbackResolver = resolver; }
  setDashGroundFireDurationResolver(resolver: ((playerId: string) => number) | null): void { this.dashGroundFireDurationResolver = resolver; }
  setDashGroundFireHandler(handler: DashGroundFireHandler | null): void { this.dashGroundFireHandler = handler; }
  setDashHoldEnabledResolver(resolver: ((playerId: string) => boolean) | null): void { this.dashHoldEnabledResolver = resolver; }
  setEnemyMovementFactorResolver(resolver: ((enemyId: string, now: number) => number) | null): void { this.enemyMovementFactorResolver = resolver; }
  setEnemyHitStaggerResolver(resolver: ((enemyId: string, now: number) => boolean) | null): void { this.enemyHitStaggerResolver = resolver; }
  setWorldMetrics(metrics: WorldMetrics | null): void {
    this.worldMetrics = metrics;
    if (metrics && !this.movementPhysicsWorld) {
      this.movementPhysicsWorld = this.scene.physics.world;
      this.movementPhysicsWorld.on('worldstep', this.consumeMovementStep);
      this.scene.events.on('postupdate', this.commitMovementStep);
    } else if (!metrics) {
      this.movementPhysicsWorld?.off('worldstep', this.consumeMovementStep);
      this.scene.events.off('postupdate', this.commitMovementStep);
      this.movementPhysicsWorld = null;
      this.movementAcknowledgements.clear();
      this.walkingSteps.clear();
    }
  }
  private waterGeometry: WaterGeometry | null = null;
  private waterPhysicsWorld: Phaser.Physics.Arcade.World | null = null;
  private readonly waterSlide = { x: 0, y: 0, vx: 0, vy: 0 };
  private readonly assistedMovementBlocked: MovementBlockedCell = (x, y) =>
    this.waterGeometry?.hasCell(x, y) === true || this.movementBlockedCellResolver?.(x, y) === true;
  /** World-owned collision pass, independent of the colliders disabled by burrowing. */
  setWaterGeometry(water: WaterGeometry | null): void {
    this.waterPhysicsWorld?.off('worldstep', this.collideWater);
    this.waterGeometry = water?.water.length ? water : null;
    this.waterPhysicsWorld = this.waterGeometry ? this.scene.physics.world : null;
    this.waterPhysicsWorld?.on('worldstep', this.collideWater);
    // Walking re-resolution reads the completed step pose, including the water pass.
    if (this.movementPhysicsWorld && this.waterPhysicsWorld) {
      this.movementPhysicsWorld.off('worldstep', this.consumeMovementStep);
      this.movementPhysicsWorld.on('worldstep', this.consumeMovementStep);
    }
  }

  private readonly collideWater = (): void => {
    if (!this.bridge.isHost() || !this.waterGeometry) return;
    const collide = (body: Phaser.Physics.Arcade.Body | null): void => {
      collidePlayerWater(body, this.waterGeometry, this.waterSlide);
    };
    for (const player of this.playerManager.getAllPlayers()) {
      if (player.active) collide(player.physicsProxy.body as Phaser.Physics.Arcade.Body | null);
    }
    this.enemyManager?.forEachEnemy(enemy => {
      if (enemy.sprite.active) collide(enemy.sprite.body as Phaser.Physics.Arcade.Body | null);
    });
  };
  /** Landing validation reads the same static bodies that block ordinary movement. */
  canOccupyCircle(x: number, y: number, radius: number): boolean {
    if (this.waterGeometry?.isCircleBlocked(x, y, radius)) return false;
    const m = this.worldMetrics;
    if (!m || ![x, y, radius].every(Number.isFinite) || radius < 0
      || x - radius < m.offsetX || y - radius < m.offsetY || x + radius > m.maxX || y + radius > m.maxY) return false;
    for (const group of [this.rockGroup, this.trunkGroup, this.baseGroup]) {
      for (const child of group?.getChildren() ?? []) {
        const body = (child as Phaser.GameObjects.GameObject & { body?: Phaser.Physics.Arcade.StaticBody }).body;
        if (!body?.enable) continue;
        const dx = x - Math.max(body.left, Math.min(x, body.right));
        const dy = y - Math.max(body.top, Math.min(y, body.bottom));
        if (dx * dx + dy * dy < radius * radius) return false;
      }
    }
    return true;
  }
  /** A position discontinuity preserves dash/impulses but never emits a trail across the jump. */
  resolvePortalExitMovement(from: {x: number; y: number}, to: {x: number; y: number}, radius: number): {x: number; y: number} {
    const distance = Math.hypot(to.x - from.x, to.y - from.y);
    const steps = Math.max(1, Math.ceil(distance / Math.max(1, radius * 0.5)));
    let safe = from;
    for (let step = 1; step <= steps; step++) {
      const point = { x: from.x + (to.x - from.x) * step / steps, y: from.y + (to.y - from.y) * step / steps };
      if (!this.canOccupyCircle(point.x, point.y, radius)) return safe;
      safe = point;
    }
    return safe;
  }

  resetMovementOrigin(id: string, x: number, y: number): void {
    const dash = this.dashStates.get(id);
    if (dash) { dash.lastGroundX = x; dash.lastGroundY = y; }
  }
  setMovementBlockedCellResolver(resolver: MovementBlockedCell | null): void {
    this.movementBlockedCellResolver = resolver;
  }
  setEnemyRockContactCallback(
    callback: ((enemyId: string, rock: RockPhysicsProxy, now: number) => void) | null,
  ): void {
    this.enemyRockContactCallback = callback;
  }

  // ── Rückstoß ─────────────────────────────────────────────────────────────

  /**
   * Startet einen zeitbasierter Rückstoß-Impuls (Quad-Ease-Out Decay über durationMs).
   * Wird in HostPhysicsSystem.update() additiv zur regulären Velocity addiert.
   * Amplitude zum Zeitpunkt t: force * (1 - t/duration)²
   *
   * Zielt der Impuls auf einen Gegner, wird er mit dessen Wegstossfaktor skaliert – das ist der
   * einzige Ort, an dem Gegner-Impulse entstehen, damit gilt der Faktor für jeden Wegstoß-Effekt.
   */
  addRecoil(playerId: string, vx: number, vy: number, durationMs = 180, sourcePlayerId?: string): void {
    if (this.mountedPlayers.has(playerId)) return;
    const knockbackFactor = this.enemyManager?.getEnemy(playerId)?.getKnockbackFactor() ?? 1;
    if (knockbackFactor <= 0) return;
    this.interruptMovement(playerId);

    const startMs = Date.now();
    const impulses = this.pendingRecoils.get(playerId) ?? [];
    impulses.push({ vx: vx * knockbackFactor, vy: vy * knockbackFactor, startMs, durationMs, sourcePlayerId });
    this.pendingRecoils.set(playerId, impulses);
    if (sourcePlayerId) {
      this.recentImpulseSources.set(playerId, {
        sourcePlayerId,
        expiresAt: startMs + durationMs + TRAIN.PLAYER_PUSH_KILL_CREDIT_GRACE_MS,
      });
    }
  }

  getRecentImpulseSource(playerId: string, now = Date.now()): string | null {
    const recent = this.recentImpulseSources.get(playerId);
    if (!recent) return null;
    if (now > recent.expiresAt) {
      this.recentImpulseSources.delete(playerId);
      return null;
    }
    if (recent.sourcePlayerId === playerId) return null;
    return recent.sourcePlayerId;
  }

  setForcedMovement(playerId: string, vx: number, vy: number): void {
    if (this.mountedPlayers.has(playerId)) return;
    if (!this.forcedMovement.has(playerId)) this.interruptMovement(playerId);
    this.forcedMovement.set(playerId, { vx, vy });
  }

  clearForcedMovement(playerId: string): void {
    this.forcedMovement.delete(playerId);
  }

  applyRadialImpulse(
    x: number,
    y: number,
    radius: number,
    force: number,
    ownerId?: string,
    selfMultiplier = 1,
    durationMs = 260,
    canAffect?: (targetId: string) => boolean,
  ): void {
    for (const player of this.playerManager.getAllPlayers()) {
      if (canAffect && !canAffect(player.id)) continue;
      if (!this.combatSystem?.isAlive(player.id)) continue;

      const dx = player.x - x;
      const dy = player.y - y;
      const dist = Math.sqrt(dx * dx + dy * dy);
      if (dist > radius) continue;

      const t = Phaser.Math.Clamp(dist / radius, 0, 1);
      const falloff = 1 - t;
      const mult = ownerId && player.id === ownerId ? selfMultiplier : 1;
      const impulse = force * falloff * mult;
      if (impulse <= 0) continue;

      const nx = dist > 0.001 ? dx / dist : 0;
      const ny = dist > 0.001 ? dy / dist : -1;
      this.addRecoil(player.id, nx * impulse, ny * impulse, durationMs, ownerId);
    }

    this.enemyManager?.forEachEnemy((enemy) => {
      if (canAffect && !canAffect(enemy.id)) return;
      const dx = enemy.sprite.x - x;
      const dy = enemy.sprite.y - y;
      const dist = Math.sqrt(dx * dx + dy * dy);
      if (dist > radius) return;

      const t = Phaser.Math.Clamp(dist / radius, 0, 1);
      const impulse = force * (1 - t);
      if (impulse <= 0) return;

      const nx = dist > 0.001 ? dx / dist : 0;
      const ny = dist > 0.001 ? dy / dist : -1;
      this.addRecoil(enemy.id, nx * impulse, ny * impulse, durationMs, ownerId);
    });
  }

  private static readonly ZERO_IMPULSE: { readonly vx: number; readonly vy: number } = { vx: 0, vy: 0 };

  private consumeImpulseVelocity(playerId: string, now: number): { vx: number; vy: number } | typeof HostPhysicsSystem.ZERO_IMPULSE {
    const impulses = this.pendingRecoils.get(playerId);
    if (!impulses || impulses.length === 0) return HostPhysicsSystem.ZERO_IMPULSE;

    let totalVx = 0;
    let totalVy = 0;
    const remaining: ExternalImpulse[] = [];

    for (const impulse of impulses) {
      const elapsed = now - impulse.startMs;
      if (elapsed >= impulse.durationMs) continue;
      const t = elapsed / impulse.durationMs;
      const factor = (1 - t) * (1 - t);
      totalVx += impulse.vx * factor;
      totalVy += impulse.vy * factor;
      remaining.push(impulse);
    }

    if (remaining.length > 0) {
      this.pendingRecoils.set(playerId, remaining);
    } else {
      this.pendingRecoils.delete(playerId);
    }

    return { vx: totalVx, vy: totalVy };
  }

  private getTimeBubbleFactor(
    playerId: string,
    x: number,
    y: number,
    now: number,
  ): number {
    if (this.burrowSystem?.isBurrowed(playerId)) return 1;
    const factor = this.timeBubbleSystem?.getPlayerMovementFactorAt(x, y, now, playerId) ?? 1;
    if (factor >= 0.999) return 1;
    return factor;
  }

  private getWorldMovementFactor(
    x: number,
    y: number,
    now: number,
  ): number {
    const factor = this.timeBubbleSystem?.getPlayerMovementFactorAt(x, y, now) ?? 1;
    if (factor >= 0.999) return 1;
    return factor;
  }

  // ── Dash-Abfragen ─────────────────────────────────────────────────────────

  /** Gibt zurück ob Spieler aktuell in Phase 1 (Burst) ist → Schießen blockiert. */
  isDashBurst(id: string): boolean { return this.dashBurstPlayers.has(id); }

  /** Gibt die aktuelle Dash-Phase zurück: 0 = kein Dash, 1 = Burst, 2 = Recovery. */
  getDashPhase(id: string): 0 | 1 | 2 {
    return (this.dashStates.get(id)?.phase ?? 0) as 0 | 1 | 2;
  }

  /** Origin belongs to the accepted dash and remains available through its recovery. */
  isBurrowDash(id: string): boolean { return this.dashStates.get(id)?.isBurrowDash ?? false; }

  // ── Dash-Handler (aufgerufen von NetworkBridge-RPC) ───────────────────────

  /**
   * Verarbeitet einen Dash-RPC vom Client.
   * Startet den kubischen Spieler-Burst, gegebenenfalls nach sicherem Burrow-Ausstieg.
   * Kein Dash wenn: tot, gestunnt, bereits dashend, oder im Stand.
   */
  handleDashRPC(playerId: string, dx: number, dy: number): void {
    const now = Date.now();
    if (!this.bridge.isHost()) return;
    if (!(this.canMoveResolver?.(playerId)
      ?? maySendWorldInput(this.bridge.getWorldParticipation(playerId)))) return;
    if (!this.combatSystem?.isAlive(playerId)) return;
    if (this.burrowSystem?.isStunned(playerId) || this.stunChecker?.(playerId, now)) return;
    if (this.dashStates.has(playerId)) return; // läuft noch → kein Spam

    const len = Math.hypot(dx, dy);
    if (!Number.isFinite(len) || len === 0) return; // kein Dash im Stand
    const player = this.playerManager.getPlayer(playerId);
    if (!player?.active || !player.physicsProxy.body) return;

    const fromBurrow = this.burrowSystem?.isBurrowed(playerId) ?? false;
    if (fromBurrow) {
      if (!this.burrowDashExitHandler?.(playerId)) return;
    } else if (this.burrowSystem?.isDashBlocked(playerId)) return;

    const speedMult = this.loadoutManager?.getSpeedMultiplier(playerId, now) ?? 1;
    const dashRangeMultiplier = Math.max(0, this.dashRangeMultiplierResolver?.(playerId) ?? 1);
    // Surface speed is the baseline for both variants; underground speed never stacks here.
    const vNorm = (this.runSpeedResolver?.(playerId) ?? PLAYER_SPEED) * speedMult * dashRangeMultiplier;

    this.interruptMovement(playerId);

    this.dashStates.set(playerId, {
      id: ++this.dashSequence,
      phase:   1,
      startMs: now,
      dirX:    dx / len,
      dirY:    dy / len,
      vNorm,
      impulseMultiplier: fromBurrow ? BURROW_DASH_IMPULSE_MULTIPLIER : 1,
      isBurrowDash: fromBurrow,
      hitIds: new Set(),
      lastGroundX: player.x,
      lastGroundY: player.y,
    });
    this.dashBurstPlayers.add(playerId);
    player.setDashScale(0.5);
    player.setCollisionRadius(PLAYER_SIZE * 0.25);
    this.dashObserver?.start(playerId, now);
  }

  /**
   * Startet einen Gegner-Ausweichschritt in Richtung (dx, dy): quadratische Zweiphasen-Kurve,
   * halbierte Trefferkugel während des Bursts. Liefert false,
   * wenn bereits ein Schritt läuft oder die Richtung leer ist.
   */
  startEnemyDash(enemyId: string, dx: number, dy: number): boolean {
    if (this.stunChecker?.(enemyId, Date.now())) return false;
    if (this.enemyDashStates.has(enemyId)) return false;
    const enemy = this.enemyManager?.getEnemy(enemyId);
    if (!enemy?.sprite.active || !this.combatSystem?.isAlive(enemyId)) return false;

    const length = Math.hypot(dx, dy);
    if (length === 0) return false;

    this.enemyDashStates.set(enemyId, {
      phase:   1,
      startMs: Date.now(),
      dirX:    dx / length,
      dirY:    dy / length,
      vNorm:   enemy.getMoveSpeed(),
    });
    enemy.setDashPhase(1);
    return true;
  }

  isEnemyDashing(enemyId: string): boolean {
    return this.enemyDashStates.has(enemyId);
  }

  // ── Burrow-Kollisions-Steuerung (aufgerufen von BurrowSystem) ────────────

  /**
   * Filtert unterirdische Kollisionen; Missionsbarrieren bleiben unpassierbar.
   * Wird von BurrowSystem beim Betreten/Verlassen des Burrow-Zustands aufgerufen.
   */
  setPlayerBurrowed(id: string, burrowed: boolean): void {
    if (burrowed !== this.burrowedPlayers.has(id)) this.interruptMovement(id);
    if (burrowed) {
      this.burrowedPlayers.add(id);
    } else {
      this.burrowedPlayers.delete(id);
    }
  }

  /**
   * Gegenstück zu {@link setPlayerBurrowed} für Coop-Defense-Gegner. Die Collider werden lazy im
   * Frame-Update angelegt; deshalb merkt sich das Set den Zustand und {@link update} hält neu
   * erzeugte Collider eines eingebuddelten Gegners inaktiv.
   */
  setEnemyBurrowed(id: string, burrowed: boolean): void {
    if (burrowed) this.burrowedEnemies.add(id);
    else this.burrowedEnemies.delete(id);
    for (const collider of this.enemyColliders.get(id) ?? []) collider.active = !burrowed;
  }

  // ── Obstacle-Gruppen ─────────────────────────────────────────────────────

  /**
   * Setzt die Kollisions-Gruppen nach dem Arena-Aufbau.
   * Bei null (Lobby-Teardown) werden alle existierenden Collider zerstört
   * und die Tracking-Sets geleert, damit die nächste Runde sauber startet.
   */
  setRockGroup(
    rockGroup:  Phaser.Physics.Arcade.StaticGroup | null,
    trunkGroup: Phaser.Physics.Arcade.StaticGroup | null,
  ): void {
    if (rockGroup === null) {
      for (const colliders of this.playerColliders.values()) {
        for (const c of colliders) c.destroy();
      }
      for (const colliders of this.enemyColliders.values()) {
        for (const c of colliders) c.destroy();
      }
      this.playerColliders.clear();
      this.enemyColliders.clear();
      this.rockCollidersSetup.clear();
      this.trunkCollidersSetup.clear();
      this.baseCollidersSetup.clear();
      this.enemyRockCollidersSetup.clear();
      this.enemyTrunkCollidersSetup.clear();
      this.enemyBaseCollidersSetup.clear();
      this.burrowedPlayers.clear();
      this.burrowedEnemies.clear();
      for (const id of this.dashStates.keys()) this.dashObserver?.end(id);
    this.dashStates.clear();
      this.dashBurstPlayers.clear();
      this.enemyDashStates.clear();
      this.pendingRecoils.clear();
      this.recentImpulseSources.clear();
      this.forcedMovement.clear();
      this.movementBlockedCellResolver = null;
      this.worldMetrics = null;
    }
    this.rockGroup  = rockGroup;
    this.trunkGroup = trunkGroup;
  }

  /**
   * Setzt die Coop-Defense-Basis-Gruppe für Spieler-Kollisionen.
   * Spieler können nicht durch Basen laufen (analog zu Felsen). Wird beim
   * Teardown (null) zurückgesetzt; die Collider werden durch den rockGroup=null-
   * Pfad in setRockGroup() bereits abgeräumt.
   */
  setBaseGroup(baseGroup: Phaser.Physics.Arcade.StaticGroup | null): void {
    this.baseGroup = baseGroup;
    if (baseGroup === null) this.baseCollidersSetup.clear();
  }

  /**
   * Spieler-Collider zerstören wenn ein Spieler die Lobby verlässt.
   */
  removePlayer(id: string): void {
    this.movementAcknowledgements.remove(id);
    this.walkingSteps.delete(id);
    this.mountedPlayers.delete(id);
    const colliders = this.playerColliders.get(id);
    if (colliders) {
      for (const c of colliders) c.destroy();
      this.playerColliders.delete(id);
    }
    this.rockCollidersSetup.delete(id);
    this.trunkCollidersSetup.delete(id);
    this.baseCollidersSetup.delete(id);
    this.burrowedPlayers.delete(id);
    this.dashObserver?.end(id);
    this.dashStates.delete(id);
    this.dashBurstPlayers.delete(id);
    this.pendingRecoils.delete(id);
    this.recentImpulseSources.delete(id);
    this.forcedMovement.delete(id);
  }

  removeEnemy(id: string): void {
    const colliders = this.enemyColliders.get(id);
    if (colliders) {
      for (const c of colliders) c.destroy();
      this.enemyColliders.delete(id);
    }
    this.enemyRockCollidersSetup.delete(id);
    this.enemyTrunkCollidersSetup.delete(id);
    this.enemyBaseCollidersSetup.delete(id);
    this.burrowedEnemies.delete(id);
    this.pendingRecoils.delete(id);
    this.recentImpulseSources.delete(id);
    this.forcedMovement.delete(id);
  }

  private recordWalkingStep(id: string, predictable: boolean, input: PlayerInput | undefined,
    speed: number, assisted: boolean, positionRevision: number): void {
    if (!predictable || !input) { this.walkingSteps.delete(id); return; }
    let walking = this.walkingSteps.get(id);
    if (!walking) this.walkingSteps.set(id, walking = { dx: 0, dy: 0, speed: 0, assisted: false, positionRevision: 0 });
    walking.dx = input.dx; walking.dy = input.dy; walking.speed = speed;
    walking.assisted = assisted; walking.positionRevision = positionRevision;
  }

  // ── Frame-Update ─────────────────────────────────────────────────────────

  /**
   * Jeden Frame – nur auf dem Host aktiv.
   * Priorität: Stun > Dash (2-Phasen) > Burrow-Speed > Normale Bewegung.
   */
  update(movementLocked = false, now = Date.now()): void {
    if (!this.bridge.isHost()) return;

    for (const enemyId of this.enemyColliders.keys()) {
      if (this.enemyManager?.hasEnemy(enemyId)) continue;
      this.removeEnemy(enemyId);
    }

    for (const player of this.playerManager.getAllPlayers()) {
      // Entity kann während Round-/Scene-Teardown noch im Manager stehen,
      // obwohl Phaser den Koerper bereits entfernt hat.
      const playerBody = player.physicsProxy.body as Phaser.Physics.Arcade.Body | null;
      if (!player.active || !playerBody) continue;
      const movementInput = this.bridge.getPlayerInput(player.id);
      let predictable = false;
      let walkingSpeed = 0;
      let walkingAssisted = false;
      try {
        const mounted = this.mountedPlayers.get(player.id);
        if (mounted) { this.setPlayerMounted(player.id, mounted); continue; }

        // Lazy: Collider mit Felsen anlegen
        if (this.rockGroup && !this.rockCollidersSetup.has(player.id)) {
          const existing = this.playerColliders.get(player.id) ?? [];
          const c = this.scene.physics.add.collider(player.physicsProxy, this.rockGroup, undefined,
            (_player, obstacle) => !this.burrowedPlayers.has(player.id) || isMissionBarrierBody(obstacle));
          existing.push(c);
          this.playerColliders.set(player.id, existing);
          this.rockCollidersSetup.add(player.id);
        }

        // Lazy: Collider mit Baumstümpfen anlegen
        if (this.trunkGroup && !this.trunkCollidersSetup.has(player.id)) {
          const existing = this.playerColliders.get(player.id) ?? [];
          const c = this.scene.physics.add.collider(player.physicsProxy, this.trunkGroup, undefined,
            (_player, obstacle) => !this.burrowedPlayers.has(player.id) || isMissionBarrierBody(obstacle));
          existing.push(c);
          this.playerColliders.set(player.id, existing);
          this.trunkCollidersSetup.add(player.id);
        }

        // Lazy: Collider mit Coop-Defense-Basen anlegen
        if (this.baseGroup && !this.baseCollidersSetup.has(player.id)) {
          const existing = this.playerColliders.get(player.id) ?? [];
          const c = this.scene.physics.add.collider(player.physicsProxy, this.baseGroup, undefined,
            (_player, obstacle) => !this.burrowedPlayers.has(player.id) || isMissionBarrierBody(obstacle));
          existing.push(c);
          this.playerColliders.set(player.id, existing);
          this.baseCollidersSetup.add(player.id);
        }

        // Tote Spieler überspringen (body.enable = false durch WorldCombatCore)
        if (!this.combatSystem?.isAlive(player.id) || this.stunChecker?.(player.id, now)) {
          this.dashObserver?.end(player.id); this.dashStates.delete(player.id); this.dashBurstPlayers.delete(player.id);
          player.setDashScale(1); player.setCollisionRadius(PLAYER_SIZE / 2); playerBody.setVelocity(0, 0); continue;
        }

        const impulse = this.consumeImpulseVelocity(player.id, now);
        const forcedMovement = this.forcedMovement.get(player.id);

        if (!(this.canMoveResolver?.(player.id)
          ?? maySendWorldInput(this.bridge.getWorldParticipation(player.id)))) {
          playerBody.setVelocity(impulse.vx, impulse.vy);
          continue;
        }

        if (movementLocked) {
          const factor = this.getTimeBubbleFactor(player.id, player.x, player.y, now);
          playerBody.setVelocity(impulse.vx * factor, impulse.vy * factor);
          continue;
        }

        if (forcedMovement) {
          const factor = this.getTimeBubbleFactor(
            player.id,
            player.x,
            player.y,
            now,
          );
          playerBody.setVelocity(
            (forcedMovement.vx + impulse.vx) * factor,
            (forcedMovement.vy + impulse.vy) * factor,
          );
          continue;
        }

        // ── 1. Stun: Keine Bewegung ───────────────────────────────────────
        if (this.burrowSystem?.isStunned(player.id)) {
          const factor = this.getTimeBubbleFactor(player.id, player.x, player.y, now);
          playerBody.setVelocity(impulse.vx * factor, impulse.vy * factor);
          continue;
        }

        let baseVx = 0;
        let baseVy = 0;

        // ── 2. Dash: 2-Phasen Speed-Debt-Modell ─────────────────────────
        const dash = this.dashStates.get(player.id);
        if (dash) {
          const elapsed = (now - dash.startMs) / 1000;

          // Air Control: WASD wenn gedrückt, sonst gespeicherte Startrichtung
          const input  = this.bridge.getPlayerInput(player.id);
          const rawX   = input?.dx ?? 0;
          const rawY   = input?.dy ?? 0;
          const rawLen = Math.sqrt(rawX * rawX + rawY * rawY);
          const dirX   = rawLen > 0 ? rawX / rawLen : dash.dirX;
          const dirY   = rawLen > 0 ? rawY / rawLen : dash.dirY;

          let speedFactor: number;
          let done = false;

          if (dash.phase === 1) {
            const timing = getDashBurstTiming(
              elapsed,
              DASH_T1_S,
              this.dashHoldEnabledResolver?.(player.id) ?? false,
              input?.dashHeld === true,
              DASH_HOLD_MAX_DURATION_FACTOR,
            );
            speedFactor = getPlayerDashBurstSpeedFactor(timing.progress, dash.impulseMultiplier);

            // Hitbox sofort auf 50 % Radius (25 % Fläche). setCollisionRadius arbeitet in
            // Display-Pixeln und kompensiert die Quelltextur-Skalierung des Spieler-Sprites.
            player.setDashScale(0.5);
            player.setCollisionRadius(PLAYER_SIZE * 0.25);
            const groundFireDurationMs = this.dashGroundFireDurationResolver?.(player.id) ?? 0;
            if (groundFireDurationMs > 0) {
              this.dashGroundFireHandler?.(
                player.id,
                `dash:${player.id}:${dash.startMs}`,
                dash.lastGroundX,
                dash.lastGroundY,
                player.x,
                player.y,
                groundFireDurationMs,
                now,
              );
              dash.lastGroundX = player.x;
              dash.lastGroundY = player.y;
            }
            this.publishDashMovement(player.id, now);
            const impactDamage = this.dashImpactDamageResolver?.(player.id) ?? 0;
            const impactKnockback = this.dashImpactKnockbackResolver?.(player.id) ?? 0;
            if (impactDamage > 0) {
              for (const enemy of this.enemyManager?.getAllEnemies() ?? []) {
                if (dash.hitIds.has(enemy.id) || !enemy.sprite.active) continue;
                if (Phaser.Math.Distance.Between(player.x, player.y, enemy.sprite.x, enemy.sprite.y) > PLAYER_SIZE) continue;
                if (this.dashObserver?.canApplyImpact?.(player.id, enemy.id) === false) continue;
                dash.hitIds.add(enemy.id);
                this.combatSystem?.applyDamage(enemy.id, impactDamage, false, player.id, 'Dash-Aufprall', { sourceX: player.x, sourceY: player.y });
                this.addRecoil(enemy.id, dirX * impactKnockback, dirY * impactKnockback, 180, player.id);
              }
            }

            if (timing.shouldEnd) {
              // Phase 2 beginnt bei Loslassen bzw. am normalen/erweiterten Zeitlimit neu.
              dash.phase   = 2;
              dash.startMs = now;
              this.dashBurstPlayers.delete(player.id);
            }
          } else {
            const recoveryDuration = Math.max(0.01, this.dashRecoveryDurationResolver?.(player.id) ?? DASH_T2_S);
            const t = Math.min(1, elapsed / recoveryDuration);
            // Quad.easeIn: zähes Aufrappeln von f_min auf 1.0
            const easeIn = t * t;
            speedFactor = DASH_F_MIN + (1 - DASH_F_MIN) * easeIn;
            const scale = 0.5 + 0.5 * easeIn;
            player.setDashScale(scale);
            player.setCollisionRadius(PLAYER_SIZE * scale / 2);
            this.publishDashMovement(player.id, now);

            if (elapsed >= recoveryDuration) {
              done = true;
              this.dashStates.delete(player.id);
              this.dashObserver?.end(player.id);
              player.setDashScale(1.0);
              player.setCollisionRadius(PLAYER_SIZE / 2);
            }
          }

          if (!done) {
            baseVx = dirX * dash.vNorm * speedFactor;
            baseVy = dirY * dash.vNorm * speedFactor;
            const factor = this.getTimeBubbleFactor(
              player.id,
              player.x,
              player.y,
              now,
            );
            playerBody.setVelocity(
              (baseVx + impulse.vx) * factor,
              (baseVy + impulse.vy) * factor,
            );
            continue;
          }
          // done → fällt durch zur normalen Bewegung
        }

        // ── 3. Normaler Input mit optionalem Burrow-Speed-Faktor ─────────
        const burrowSpeedFactor = this.burrowSystem?.getMovementSpeedFactor(player.id) ?? 1;
        const speedMult  = this.loadoutManager?.getSpeedMultiplier(player.id, now) ?? 1;
        const speed      = (this.runSpeedResolver?.(player.id) ?? PLAYER_SPEED) * burrowSpeedFactor * speedMult * ((this.walkingSpeedMultiplierResolver?.(player.id, now) ?? 1) * (1 + (this.zeusMoveBonus?.(player.id, now) ?? 0)));

        walkingAssisted = !this.burrowSystem?.isBurrowed(player.id)
          && !!(this.movementBlockedCellResolver || this.waterGeometry);
        // The body already holds this frame's completed steps; the proxy only follows at POST_UPDATE.
        resolveWalkingVelocity(playerBody.center.x, playerBody.center.y, movementInput?.dx ?? 0,
          movementInput?.dy ?? 0, speed, this.worldMetrics,
          walkingAssisted ? this.assistedMovementBlocked : null, this.gridCornerAssistOutput);
        baseVx = this.gridCornerAssistOutput.dx;
        baseVy = this.gridCornerAssistOutput.dy;

        const selfPush = this.loadoutManager?.getHeldSelfPushVelocity(player.id, now);
        if (selfPush) {
          baseVx += selfPush.vx;
          baseVy += selfPush.vy;
        }

        const factor = this.getTimeBubbleFactor(
          player.id,
          player.x,
          player.y,
          now,
        );
        walkingSpeed = speed * factor;
        predictable = !selfPush && !this.pendingRecoils.has(player.id)
          && !this.burrowSystem?.isBurrowed(player.id)
          && (this.burrowSystem?.getPhase?.(player.id) ?? 'idle') === 'idle';
        playerBody.setVelocity(
          (baseVx + impulse.vx) * factor,
          (baseVy + impulse.vy) * factor,
        );
      } finally {
        this.movementAcknowledgements.select(player.id, player.positionRevision,
          movementInput?.movementSequence, walkingSpeed, predictable);
        this.recordWalkingStep(player.id, predictable, movementInput, walkingSpeed, walkingAssisted, player.positionRevision);
      }
    }

    this.enemyManager?.forEachEnemy((enemy) => {
      const enemyBody = enemy.sprite.body as Phaser.Physics.Arcade.Body | null;
      if (!enemy.sprite.active || !enemyBody) return;

      if (this.rockGroup && !this.enemyRockCollidersSetup.has(enemy.id)) {
        const existing = this.enemyColliders.get(enemy.id) ?? [];
        existing.push(this.scene.physics.add.collider(enemy.sprite, this.rockGroup, (_enemy, rockObject) => {
          const rock = rockObject as RockPhysicsProxy;
          if (!rock.active) return;
          this.enemyRockContactCallback?.(enemy.id, rock, Date.now());
        }));
        this.enemyColliders.set(enemy.id, existing);
        this.enemyRockCollidersSetup.add(enemy.id);
      }

      if (this.trunkGroup && !this.enemyTrunkCollidersSetup.has(enemy.id)) {
        const existing = this.enemyColliders.get(enemy.id) ?? [];
        existing.push(this.scene.physics.add.collider(enemy.sprite, this.trunkGroup));
        this.enemyColliders.set(enemy.id, existing);
        this.enemyTrunkCollidersSetup.add(enemy.id);
      }

      if (this.baseGroup && !this.enemyBaseCollidersSetup.has(enemy.id)) {
        const existing = this.enemyColliders.get(enemy.id) ?? [];
        existing.push(this.scene.physics.add.collider(enemy.sprite, this.baseGroup));
        this.enemyColliders.set(enemy.id, existing);
        this.enemyBaseCollidersSetup.add(enemy.id);
      }

      // Eingebuddelte Gegner kollidieren mit nichts – auch nicht mit erst hier lazy erzeugten Collidern.
      if (this.burrowedEnemies.has(enemy.id)) {
        for (const collider of this.enemyColliders.get(enemy.id) ?? []) collider.active = false;
      }

      const impulse = this.consumeImpulseVelocity(enemy.id, now);
      const dashVelocity = this.advanceEnemyDash(enemy, now);
      const desiredVelocity = dashVelocity ?? enemy.getDesiredVelocity();
      // The dash clock keeps running; stagger suppresses propulsion, never external impulses.
      if (this.stunChecker?.(enemy.id, now)) { this.endEnemyDash(enemy); enemyBody.setVelocity(0, 0); enemy.setWalking(false); return; }
      const hitStaggerFactor = this.enemyHitStaggerResolver?.(enemy.id, now) ? 0 : 1;
      const worldFactor = this.getWorldMovementFactor(
        enemy.sprite.x,
        enemy.sprite.y,
        now,
      );
      const enemyMovementFactor = Phaser.Math.Clamp(this.enemyMovementFactorResolver?.(enemy.id, now) ?? 1, 0, 1);
      const combinedFactor = worldFactor * enemyMovementFactor;
      enemyBody.setVelocity(
        (desiredVelocity.vx * hitStaggerFactor + impulse.vx) * combinedFactor,
        (desiredVelocity.vy * hitStaggerFactor + impulse.vy) * combinedFactor,
      );
      enemy.setWalking(isVelocityMoving(enemyBody.velocity.x, enemyBody.velocity.y));
      // Visual sync (HP bar, boss decorations, glow, burn, fuse) is handled
      // centrally by EnemyManager.syncHostVisuals() later in the frame,
      // after combat resolution and status updates have been applied.
    });

    // Stirbt ein Gegner mitten im Ausweichschritt, bleibt sein Eintrag sonst bis zum Rundenende liegen.
    for (const enemyId of this.enemyDashStates.keys()) {
      if (!this.enemyManager?.hasEnemy(enemyId)) this.enemyDashStates.delete(enemyId);
    }
  }

  /**
   * Schreibt einen laufenden Gegner-Ausweichschritt fort und liefert dessen Wunschgeschwindigkeit;
   * null, wenn kein Schritt läuft (dann gilt die normale Wegfindung).
   *
   * Eigene Gegner-Kurve: Phase 1 fällt per Quad.easeOut von
   * ENEMY_DASH_F_START auf DASH_F_MIN und halbiert die Trefferkugel, Phase 2 rappelt sich per
   * Quad.easeIn auf 1.0 zurück. Ohne Air-Control und ohne Upgrade-Resolver – Standard-Dash.
   */
  private advanceEnemyDash(enemy: EnemyEntity, now: number): { vx: number; vy: number } | null {
    const dash = this.enemyDashStates.get(enemy.id);
    if (!dash) return null;

    // Unter der Erde bzw. im Tod bricht der Schritt sofort ab, damit die Hitbox nicht klein bleibt.
    if (enemy.isBurrowed() || !this.combatSystem?.isAlive(enemy.id)) {
      this.endEnemyDash(enemy);
      return null;
    }

    const elapsed = (now - dash.startMs) / 1000;
    let speedFactor: number;

    if (dash.phase === 1) {
      const timing = getDashBurstTiming(elapsed, DASH_T1_S, false, false, DASH_HOLD_MAX_DURATION_FACTOR);
      const easeOut = 1 - (1 - timing.progress) * (1 - timing.progress);
      speedFactor = ENEMY_DASH_F_START + (DASH_F_MIN - ENEMY_DASH_F_START) * easeOut;
      enemy.setDashScale(0.5);

      if (timing.shouldEnd) {
        dash.phase = 2;
        dash.startMs = now;
        enemy.setDashPhase(2);
      }
    } else {
      const t = Math.min(1, elapsed / DASH_T2_S);
      const easeIn = t * t;
      speedFactor = DASH_F_MIN + (1 - DASH_F_MIN) * easeIn;
      enemy.setDashScale(0.5 + 0.5 * easeIn);

      if (elapsed >= DASH_T2_S) {
        this.endEnemyDash(enemy);
        return null;
      }
    }

    return { vx: dash.dirX * dash.vNorm * speedFactor, vy: dash.dirY * dash.vNorm * speedFactor };
  }

  private endEnemyDash(enemy: EnemyEntity): void {
    this.enemyDashStates.delete(enemy.id);
    enemy.setDashPhase(0);
    enemy.setDashScale(1);
  }
}
